#include <bits/stdc++.h>
using namespace std;

struct State {
    int left, right, up, down;
    unsigned char corners;

    bool operator==(const State& other) const {
        return left == other.left && right == other.right &&
               up == other.up && down == other.down &&
               corners == other.corners;
    }
};

struct StateHash {
    size_t operator()(const State& s) const {
        size_t h = 0;
        auto combine = [&](size_t x) {
            h ^= x + 0x9e3779b97f4a7c15ULL + (h << 6) + (h >> 2);
        };
        combine(hash<int>{}(s.left));
        combine(hash<int>{}(s.right));
        combine(hash<int>{}(s.up));
        combine(hash<int>{}(s.down));
        combine(hash<unsigned int>{}(s.corners));
        return h;
    }
};

unordered_map<State, unsigned char, StateHash> memo;

bool solve(int left, int right, int up, int down, unsigned char corners) {
    if (corners == 0) {
        return ((left % 3) ^ (right % 3) ^ (up % 3) ^ (down % 3)) != 0;
    }

    State state{left, right, up, down, corners};
    auto it = memo.find(state);
    if (it != memo.end()) return it->second;

    auto losing = [&](int l, int r, int u, int d, unsigned char c) {
        return !solve(l, r, u, d, c);
    };

    constexpr unsigned char UL = 1 << 0;
    constexpr unsigned char UR = 1 << 1;
    constexpr unsigned char DL = 1 << 2;
    constexpr unsigned char DR = 1 << 3;

    if (corners & UL) {
        unsigned char next = corners ^ UL;
        if (losing(left, right, up, down, next) ||
            (up > 0 && losing(left, right, up - 1, down, next)) ||
            (left > 0 && losing(left - 1, right, up, down, next))) {
            memo[state] = 1;
            return true;
        }
    }

    if (corners & UR) {
        unsigned char next = corners ^ UR;
        if (losing(left, right, up, down, next) ||
            (up > 0 && losing(left, right, up - 1, down, next)) ||
            (right > 0 && losing(left, right - 1, up, down, next))) {
            memo[state] = 1;
            return true;
        }
    }

    if (corners & DL) {
        unsigned char next = corners ^ DL;
        if (losing(left, right, up, down, next) ||
            (down > 0 && losing(left, right, up, down - 1, next)) ||
            (left > 0 && losing(left - 1, right, up, down, next))) {
            memo[state] = 1;
            return true;
        }
    }

    if (corners & DR) {
        unsigned char next = corners ^ DR;
        if (losing(left, right, up, down, next) ||
            (down > 0 && losing(left, right, up, down - 1, next)) ||
            (right > 0 && losing(left, right - 1, up, down, next))) {
            memo[state] = 1;
            return true;
        }
    }

    if ((left > 0 && losing(left - 1, right, up, down, corners)) ||
        (left > 1 && losing(left - 2, right, up, down, corners)) ||
        (right > 0 && losing(left, right - 1, up, down, corners)) ||
        (right > 1 && losing(left, right - 2, up, down, corners)) ||
        (up > 0 && losing(left, right, up - 1, down, corners)) ||
        (up > 1 && losing(left, right, up - 2, down, corners)) ||
        (down > 0 && losing(left, right, up, down - 1, corners)) ||
        (down > 1 && losing(left, right, up, down - 2, corners))) {
        memo[state] = 1;
        return true;
    }

    memo[state] = 0;
    return false;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int a, b, r;
    cin >> a >> b >> r;

    int left = a / (2 * r);
    int right = 0;
    if (b / 2 >= 2 * r) right = left;

    int up = b / (2 * r);
    int down = 0;
    if (a / 2 >= 2 * r) down = up;

    unsigned char corners = 0;
    constexpr unsigned char UL = 1 << 0;
    constexpr unsigned char UR = 1 << 1;
    constexpr unsigned char DL = 1 << 2;
    constexpr unsigned char DR = 1 << 3;

    if (up && left) {
        corners |= UL;
        --up;
        --left;
    }
    if (up && right) {
        corners |= UR;
        --up;
        --right;
    }
    if (down && left) {
        corners |= DL;
        --down;
        --left;
    }
    if (down && right) {
        corners |= DR;
        --down;
        --right;
    }

    cout << (solve(left, right, up, down, corners) ? "First\n" : "Second\n");
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

int maxLeft, maxRight, maxUp, maxDown;
vector<unsigned char> dp;

uint64_t stateIndex(int left, int right, int up, int down,
                    int upleft, int upright, int downleft, int downright) {
    uint64_t index = left;
    index = index * (maxRight + 1ULL) + right;
    index = index * (maxUp + 1ULL) + up;
    index = index * (maxDown + 1ULL) + down;
    index = (index << 1) | upleft;
    index = (index << 1) | upright;
    index = (index << 1) | downleft;
    index = (index << 1) | downright;
    return index;
}

int getState(uint64_t index) {
    int shift = static_cast<int>((index & 3ULL) * 2);
    return (dp[index >> 2] >> shift) & 3;
}

bool setState(uint64_t index, bool value) {
    int shift = static_cast<int>((index & 3ULL) * 2);
    unsigned char mask = static_cast<unsigned char>(3U << shift);
    unsigned char stored = static_cast<unsigned char>((value ? 2U : 1U) << shift);
    dp[index >> 2] = static_cast<unsigned char>((dp[index >> 2] & ~mask) | stored);
    return value;
}

bool solve(int left, int right, int up, int down,
           int upleft, int upright, int downleft, int downright) {
    if (left < 0 || right < 0 || up < 0 || down < 0 ||
        upleft < 0 || upright < 0 || downleft < 0 || downright < 0) {
        return true;
    }

    if (left + right + up + down +
        upleft + upright + downleft + downright == 0) {
        return false;
    }

    uint64_t index = stateIndex(left, right, up, down,
                                upleft, upright, downleft, downright);
    int cached = getState(index);
    if (cached != 0) return cached == 2;

    auto winningMove = [&](int dl, int dr, int du, int dd,
                           int dul, int dur, int ddl, int ddr) {
        return !solve(left - dl, right - dr, up - du, down - dd,
                      upleft - dul, upright - dur,
                      downleft - ddl, downright - ddr);
    };

    if (winningMove(0, 0, 0, 0, 1, 0, 0, 0) ||
        winningMove(0, 0, 1, 0, 1, 0, 0, 0) ||
        winningMove(1, 0, 0, 0, 1, 0, 0, 0) ||

        winningMove(0, 0, 0, 0, 0, 1, 0, 0) ||
        winningMove(0, 0, 1, 0, 0, 1, 0, 0) ||
        winningMove(0, 1, 0, 0, 0, 1, 0, 0) ||

        winningMove(0, 0, 0, 0, 0, 0, 1, 0) ||
        winningMove(0, 0, 0, 1, 0, 0, 1, 0) ||
        winningMove(1, 0, 0, 0, 0, 0, 1, 0) ||

        winningMove(0, 0, 0, 0, 0, 0, 0, 1) ||
        winningMove(0, 0, 0, 1, 0, 0, 0, 1) ||
        winningMove(0, 1, 0, 0, 0, 0, 0, 1) ||

        winningMove(1, 0, 0, 0, 0, 0, 0, 0) ||
        winningMove(2, 0, 0, 0, 0, 0, 0, 0) ||
        winningMove(0, 1, 0, 0, 0, 0, 0, 0) ||
        winningMove(0, 2, 0, 0, 0, 0, 0, 0) ||
        winningMove(0, 0, 1, 0, 0, 0, 0, 0) ||
        winningMove(0, 0, 2, 0, 0, 0, 0, 0) ||
        winningMove(0, 0, 0, 1, 0, 0, 0, 0) ||
        winningMove(0, 0, 0, 2, 0, 0, 0, 0)) {
        return setState(index, true);
    }

    return setState(index, false);
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int a, b, r;
    cin >> a >> b >> r;

    int left = a / (2 * r), right = 0;
    int up = b / (2 * r), down = 0;
    int upleft = 0, upright = 0, downleft = 0, downright = 0;

    if (b / 2 >= 2 * r) right = left;
    if (a / 2 >= 2 * r) down = up;

    if (up && left) {
        ++upleft;
        --up;
        --left;
    }
    if (up && right) {
        ++upright;
        --up;
        --right;
    }
    if (down && left) {
        ++downleft;
        --down;
        --left;
    }
    if (down && right) {
        ++downright;
        --down;
        --right;
    }

    maxLeft = left;
    maxRight = right;
    maxUp = up;
    maxDown = down;

    uint64_t stateCount = static_cast<uint64_t>(maxLeft + 1) *
                          (maxRight + 1ULL) *
                          (maxUp + 1ULL) *
                          (maxDown + 1ULL) * 16ULL;
    dp.assign(static_cast<size_t>((stateCount + 3) / 4), 0);

    cout << (solve(left, right, up, down,
                   upleft, upright, downleft, downright)
                 ? "First\n"
                 : "Second\n");
