    if(b/2>=2*r)right=left;

    up=b/(2*r); down=0;
    if(a/2>=2*r)down=up;

    if(up && left)upleft++,up--,left--;
    if(up &&  right)upright++,up--,right--;
    if(down && left)downleft++,down--,left--;
    if(down && right)downright++,down--,right--;

  //cout<<left<<right<<up<<down<<upleft<<upright<<downleft<<downright<<endl;

    if(solve(left,right,up,down,upleft,upright,downleft,downright))cout<<"First\n";
    else cout<<"Second\n";
}
